      "newContent": "package com.acme.shortener.qr;

import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.containsString;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.acme.shortener.TestcontainersConfiguration;
import com.acme.shortener.link.Link;
import com.acme.shortener.link.LinkRepository;
import java.time.Clock;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Import;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

/**
 * GET /{code}/qr end to end over real Postgres and Redis. Covers AC-1 to AC-10 (FR-1 to FR-5, NFR-1
 * to NFR-3). Links are stored through the repository: the QR endpoint only reads them.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(TestcontainersConfiguration.class)
class QrCodeIT {

  private static final String PROBLEM_JSON = "application/problem+json";

  @Autowired MockMvc mvc;
  @Autowired LinkRepository links;

  @Test
  void anActiveLinkGetsAPngThatEncodesItsShortUrl() throws Exception {
    String code = activeLink();

    byte[] png =
        mvc.perform(get("/" + code + "/qr")) // AC-8: no API key
            .andExpect(status().isOk())
            .andExpect(content().contentType("image/png"))
            .andExpect(header().string("Cache-Control", containsString("max-age=0")))
            .andExpect(header().string("Cache-Control", containsString("private")))
            .andReturn()
            .getResponse()
            .getContentAsByteArray();

    // AC-1 and NFR-3: the short URL, never the original URL
    assertThat(QrCodes.decode(png)).isEqualTo("http://sho.rt/" + code);
    assertThat(QrCodes.image(png).getWidth()).isEqualTo(256); // AC-2: the default size
  }

  @Test
  void theSizeParameterSetsThePixelSizeWithinItsRange() throws Exception {
    String code = activeLink();

    for (int size : new int[] {128, 1024}) { // AC-3
      byte[] png = png(code, size);
      assertThat(QrCodes.image(png).getWidth()).isEqualTo(size);
      assertThat(QrCodes.image(png).getHeight()).isEqualTo(size);
      assertThat(QrCodes.decode(png)).isEqualTo("http://sho.rt/" + code);
    }
    assertThat(png(code, 300)).isEqualTo(png(code, 300)); // AC-9: byte-identical
  }

  @Test
  void aSizeOutsideTheRangeIsAProblem() throws Exception {
    String code = activeLink();

    for (String size : new String[] {"127", "1025", "0", "-5"}) { // AC-4
      expectProblem(mvc.perform(get("/" + code + "/qr").param("size", size)), 400)
          .andExpect(jsonPath("$.type").value("/problems/invalid-qr-size"))
          .andExpect(jsonPath("$.detail", containsString("between 128 and 1024")));
    }
    expectProblem(mvc.perform(get("/" + code + "/qr").param("size", "big")), 400) // AC-5
        .andExpect(jsonPath("$.type").value("/problems/validation-failed"));
  }

  @Test
  void unknownAndDeletedLinksGetNoQrCode() throws Exception {
    expectProblem(mvc.perform(get("/nolink" + suffix() + "/qr")), 404) // AC-6
        .andExpect(jsonPath("$.type").value("/problems/link-not-found"));

    Link link = save("qrdel" + suffix());
    mvc.perform(get("/" + link.code() + "/qr")).andExpect(status().isOk());
    links.save(link.markDeleted(Clock.systemUTC()));

    expectProblem(mvc.perform(get("/" + link.code() + "/qr")), 404) // AC-7: at once
        .andExpect(jsonPath("$.type").value("/problems/link-not-found"));
  }

  // ---- helpers ----

  private String activeLink() {
    return save("qr" + suffix()).code();
  }

  private Link save(String code) {
    return links.save(
        Link.newAlias(
            links.nextId(), code, "https://example.com/" + code, "tester", Clock.systemUTC()));
  }

  private byte[] png(String code, int size) throws Exception {
    return mvc.perform(get("/" + code + "/qr").param("size", String.valueOf(size)))
        .andExpect(status().isOk())
        .andReturn()
        .getResponse()
        .getContentAsByteArray();
  }

  private static ResultActions expectProblem(ResultActions result, int status) throws Exception {
    return result
        .andExpect(status().is(status))
        .andExpect(content().contentTypeCompatibleWith(PROBLEM_JSON));
  }

  private static String suffix() {
    return UUID.randomUUID().toString().replace("-", "").substring(0, 8);
  }
}
